INSERT INTO `bonk_weapon_locale` (`id`, `locale`, `name`, `description`)
VALUES
  (7, 'zhCN', '奥术射击', '射击最近的敌人，造成奥术伤害。'),
  (37, 'zhCN', '多重射击', '朝最近的敌人方向，打击18码锥形范围内的最多6个敌人。'),
  (38, 'zhCN', '毒蛇钉刺', '钉刺最近的敌人及其附近的2个敌人，施加3层中毒。'),
  (137, 'zhCN', '乱射', '向20码内最大的敌群降下箭雨，持续4秒，目标身上每有一种不同的减益效果，伤害提高5%。每25次命中会为你的瞄准射击装填爆炸箭，最多2支。'),
  (201, 'zhCN', '召唤宠物', '召唤一只猫为你而战。它的攻击施加1层流血，爪击施加4层，横扫则命中其前方的所有敌人。'),
  (202, 'zhCN', '爆炸陷阱', '放置一个火焰陷阱，在敌人靠近时爆炸，造成伤害并灼烧地面4秒，施加燃烧。'),
  (203, 'zhCN', '瞄准射击', '发射一发贯穿直线上所有敌人的射击，造成伤害。优先瞄准被标记的敌群，其次瞄准最大的敌群。装填爆炸箭时，该射击会在首次命中时爆炸，对8码内的所有敌人造成其伤害。'),
  (204, 'zhCN', '毒蛇陷阱', '放置一个陷阱，在敌人靠近时放出4条毒蛇。每条毒蛇会冲向最近的4个敌人之一，爆裂成一团毒云，持续4秒。范围内的敌人每0.5秒获得1层中毒。'),
  (205, 'zhCN', '猎人印记', '标记最大的敌群周围10码内的所有敌人，持续8秒。被标记的敌人受到的伤害提高15%。'),
  (211, 'zhCN', '狼群首领', '一只灵魂之狼为你而战，撕咬造成伤害。它会每隔15秒嚎叫一次，使你的其他宠物对前方所有敌人造成的伤害翻倍，持续6秒。你的宠物的撕咬会施加猎人印记。'),
  (212, 'zhCN', '奇美拉射击', '射击最近的敌人，造成奥术伤害，并消耗其身上所有中毒效果，立即造成剩余的毒性伤害。'),
  (213, 'zhCN', '弹射', '射击最近的敌人，造成奥术伤害，然后弹向10码内的2个敌人，被标记的敌人优先。每跳伤害比上一跳提高25%。'),
  (214, 'zhCN', '花式射击', '向前方锥形范围内射出3支箭，造成伤害。被射杀的每个敌人会向15码内最近的敌人再射出3支箭，被射杀的目标还会继续触发。'),
  (215, 'zhCN', '毒液扩散', '向前方锥形范围内射出3支箭，造成伤害并施加2层中毒。'),
  (216, 'zhCN', '连锁爆破', '发射一发贯穿直线上所有敌人的射击，造成伤害。优先瞄准被标记的敌群，其次瞄准最大的敌群。被贯穿的每个敌人会依次爆炸，对其4码内的敌人造成40%的伤害。装填爆炸箭时，该射击会在首次命中时爆炸，对8码内的所有敌人造成其伤害。'),
  (217, 'zhCN', '稳固瞄准', '发射一发贯穿直线上所有敌人的射击，造成伤害。优先瞄准被标记的敌群，其次瞄准最大的敌群。站立不动时，其攻击频率翻倍，射线宽度每秒增加100%，最多可达3倍宽。装填爆炸箭时，该射击会在首次命中时爆炸，对8码内的所有敌人造成其伤害。'),
  (218, 'zhCN', '箭雨风暴', '向最大的敌群倾泻箭雨，持续3秒并造成伤害，目标身上每种不同的减益效果都使伤害提高5%。风暴会跟随25码内最大的敌群移动。每命中25个敌人，就会为你的瞄准射击装填一支爆炸箭，最多装填2支。'),
  (219, 'zhCN', '重力乱射', '将最大的敌群周围12码内的所有普通敌人拉向中央，然后向他们倾泻箭雨，持续3秒并造成伤害，目标身上每种不同的减益效果都使伤害提高5%。精英和首领不受牵引影响。每命中25个敌人，就会为你的瞄准射击装填一支爆炸箭，最多装填2支。'),
  (220, 'zhCN', '曳光弹', '标记最大的敌群周围10码内的所有敌人，持续8秒。被标记的敌人受到的伤害提高15%。在6秒内，你的射击命中该区域的敌人时，会额外向该区域的另一个敌人射出1发。'),
  (221, 'zhCN', '死亡标记', '标记最大的敌群周围10码内的所有敌人，持续8秒。被标记的敌人受到的伤害提高15%，死亡时爆裂，对其8码内的敌人造成奥术伤害。'),
  (222, 'zhCN', '毒液箭', '钉刺最近的敌人及其附近的2个敌人，施加3层中毒。中毒的敌人死亡时会向12码内的敌人射出3支毒箭，每支施加2层中毒。'),
  (223, 'zhCN', '毒云', '钉刺最近的敌人及其附近的2个敌人，施加3层中毒。中毒的敌人死亡时会留下一团毒云，持续2秒，每0.5秒对其4码内的敌人施加1层中毒。'),
  (224, 'zhCN', '集束陷阱', '放置一个火焰陷阱，在敌人靠近时爆炸，造成伤害并灼烧地面4秒，施加燃烧。同时散布5枚子炸弹，在3码内以40%的伤害爆炸，施加燃烧。'),
  (225, 'zhCN', '易爆陷阱', '放置一个火焰陷阱，在敌人靠近时爆炸，造成伤害并点燃地面，持续4秒，施加燃烧。2秒后它会再次爆炸，造成60%的伤害。'),
  (226, 'zhCN', '腐蚀毒蛇', '放置一个陷阱，在敌人靠近时放出4条毒蛇。每条毒蛇会冲向最近的4个敌人之一，爆裂成一团毒云，持续4秒。范围内的敌人每0.5秒获得1层中毒和1层自然易伤。'),
  (227, 'zhCN', '毒液爆发', '放置一个陷阱，在敌人靠近时放出4条毒蛇。每条毒蛇会冲向最近的4个敌人之一并爆炸，对5码内的敌人造成自然伤害并施加5层中毒，然后留下一团毒云，持续2秒。范围内的敌人每0.5秒获得1层中毒。'),
  (228, 'zhCN', '兽群奔腾', '召唤你的猫为你而战。它的爪击会施加流血。每隔20秒，3头幽灵野兽会冲过最大的敌群，撞倒沿途的所有敌人。'),
  (229, 'zhCN', '瘟疫野兽', '召唤一头亡灵野兽为你而战。它的爪击会施加2层中毒，其瘟疫之云每秒对5码内的敌人施加1层中毒。'),
  (230, 'zhCN', '狼群首领之嚎', '一只灵魂之狼为你而战，撕咬造成伤害。它会每隔15秒嚎叫一次：使你的其他宠物对前方所有敌人造成的伤害翻倍，持续6秒，并有一头野猪、熊或双足飞龙加入，持续8秒。野猪会冲撞最大的敌群，熊会重击并使敌人流血，双足飞龙使你的宠物造成的伤害提高20%。你的宠物的撕咬会施加猎人印记。'),
  (231, 'zhCN', '觅食狂潮', '一只灵魂之狼为你而战，撕咬造成伤害。它会每隔15秒嚎叫一次：使你的其他宠物对前方所有敌人造成的伤害翻倍，持续6秒。期间你的宠物每击杀一个敌人，效果延长0.5秒，最多延长至10秒。你的宠物的撕咬会施加猎人印记。'),
  (300, 'zhCN', '顺劈斩', '打击你10码内的所有敌人。'),
  (301, 'zhCN', '撕裂', '使10码内最近的3个敌人受伤，施加3层流血。你的顺劈斩、旋风斩和雷霆一击命中时也会施加1层流血。'),
  (302, 'zhCN', '重伤', '你的致命一击会使敌人受伤，施加2层流血，每个敌人每0.5秒至多触发一次。面对流血的敌人时，你每层流血使致命一击几率提高1%，最多提高20%。'),
  (303, 'zhCN', '致死打击', '打击你10码内的所有敌人，目标每层流血使伤害提高8%，最多计算30层。流血状态的敌人还会立即承受其流血在未来2秒内本应造成的伤害，并保留层数。'),
  (304, 'zhCN', '嗜血', '打击10码内最近的3个敌人，并每命中一个敌人为你恢复0.5%最大生命值，最多2.5%。其致命一击会使你进入狂怒状态：急速提高25%，持续4秒。'),
  (305, 'zhCN', '斩杀', '打击你10码内的所有敌人。生命值低于20%的普通敌人立即死亡；生命值低于20%的精英和首领受到三倍伤害。其击杀会使你进入狂怒状态：急速提高25%，持续4秒。'),
  (306, 'zhCN', '旋风斩', '旋转并打击你8码内的所有敌人，造成伤害。你处于狂怒状态时会旋转两次。'),
  (307, 'zhCN', '盾牌格挡', '获得一层护盾，可吸收相当于10%最大生命值的伤害，存留直至吸收伤害，最多叠加至50%。'),
  (308, 'zhCN', '雷霆一击', '轰击你8码内的所有敌人，造成伤害。被击中的敌人攻击速度降低20%，持续6秒。'),
  (309, 'zhCN', '复仇', '当你受到攻击时，打击你10码内的所有敌人，每2秒至多触发一次。'),
  (310, 'zhCN', '盾牌猛击', '猛击你10码内的所有敌人，你的护盾每相当于1%最大生命值，伤害提高2%，最多提高200%。'),
  (311, 'zhCN', '刀锋之痕', '打击你8码内的所有敌人，造成伤害。每次挥击都会留下一道刀锋残影，在1秒后再次打击。'),
  (312, 'zhCN', '第四击', '打击你8码内的所有敌人，造成伤害。每第4次挥击可延伸至12码，并击退普通敌人。'),
  (313, 'zhCN', '血腥光环', '你8码内的所有敌人获得2层流血。你的顺劈斩、旋风斩和雷霆一击命中时也会施加1层流血。'),
  (314, 'zhCN', '血池', '使10码内最近的3个敌人受伤，施加3层流血。流血的敌人死亡时会留下一池鲜血，持续4秒，每秒对4码内的敌人施加1层流血。你的顺劈斩、旋风斩和雷霆一击命中时也会施加1层流血。'),
  (315, 'zhCN', '血溅', '你的致命一击会使敌人及其4码内的所有敌人受伤，施加2层流血，每个敌人每0.5秒至多触发一次。面对流血的敌人时，你每层流血使致命一击几率提高1%，最多提高20%。'),
  (316, 'zhCN', '出血', '你的致命一击会使敌人受伤，施加2层流血，每个敌人每0.5秒至多触发一次。该流血效果每造成一次伤害，其伤害就提高10%，最多提高至三倍。面对流血的敌人时，你每层流血使致命一击几率提高1%，最多提高20%。'),
  (317, 'zhCN', '血之渴', '打击你8码内的所有敌人，造成伤害，目标每层流血使伤害提高8%，最多计算30层。每击中一个流血的敌人，此法术的冷却时间缩短0.5秒，每次打击最多缩短1秒，冷却时间最低为3秒。被其击中的流血敌人还会额外承受其流血效果在接下来2秒内本应造成的伤害，并保留原有层数。'),
  (318, 'zhCN', '余震', '打击你8码内的所有敌人，造成伤害，目标每层流血使伤害提高8%，最多计算30层。1.5秒后地面喷发，对8码内的敌人造成30%的伤害并施加1层流血。被其击中的流血敌人还会额外承受其流血效果在接下来2秒内本应造成的伤害，并保留原有层数。'),
  (319, 'zhCN', '血盾', '打击你8码内最近的3个敌人，造成伤害，并每命中一个敌人为你恢复0.5%最大生命值，最多2.5%。溢出满生命值的治疗会转化为血盾，破碎时对8码内的敌人造成200%的伤害。'),
  (320, 'zhCN', '血浴', '打击你8码内最近的3个敌人，造成伤害，并每命中一个敌人为你恢复0.5%最大生命值，最多2.5%。生命值低于50%时，改为打击你8码内的所有敌人，治疗量最多为4%。'),
  (321, 'zhCN', '连锁斩杀', '打击你8码内的所有敌人，造成伤害。生命值低于20%的普通敌人立即死亡；生命值低于20%的精英和首领受到三倍伤害。被击杀的敌人会爆炸，对5码内的敌人造成50%的伤害，并斩杀其中生命值低于20%的普通敌人。击杀会使你进入狂怒状态。'),
  (322, 'zhCN', '横扫', '打击你8码内的所有敌人，造成伤害；生命值低于20%的精英和首领受到三倍伤害。40码内所有生命值低于20%的普通敌人立即死亡。击杀会使你进入狂怒状态：急速提高25%，持续4秒。'),
  (323, 'zhCN', '剑刃风暴', '持续旋转3秒，期间你可以继续移动，每0.5秒打击你8码内的所有敌人，造成伤害。急速越高，打击越频繁。在狂怒状态下发动时，旋转持续时间延长50%。'),
  (324, 'zhCN', '钢铁气旋', '旋转并打击你8码内的所有敌人，造成伤害；你处于狂怒状态时会旋转两次。每次旋转都会留下一场刀刃风暴，持续3秒，每0.5秒对8码内的敌人造成20%的伤害。'),
  (325, 'zhCN', '神盾护体', '获得一层护盾，可吸收相当于10%最大生命值的伤害，存留直至吸收伤害。护盾每吸收一次攻击就会发出一道冲击波，对你8码内的所有敌人造成伤害，每0.5秒至多触发一次。'),
  (326, 'zhCN', '尖刺护盾', '获得一层护盾，可吸收相当于10%最大生命值的伤害，存留直至吸收伤害。只要你持有任意护盾，尖刺就会每秒打击你8码内的所有敌人，造成伤害。'),
  (327, 'zhCN', '滚滚雷霆', '轰击你8码内的所有敌人，造成伤害，由你的其他法术触发而非冷却时间。被击中的敌人攻击速度降低20%，持续6秒。急速会降低触发所需的施法次数，最低为4次。'),
  (328, 'zhCN', '挫志怒吼', '轰击你8码内的所有敌人，造成伤害。被击中的敌人攻击速度降低20%，造成的伤害降低20%，持续6秒。每命中一个敌人为你恢复0.3%最大生命值，最多2%。'),
  (329, 'zhCN', '报复', '当你受到攻击时，打击你6码内的所有敌人，造成伤害，每2秒至多触发一次。你受到的生命伤害会被储存，最多储存50%最大生命值，并使下一次打击的伤害提高，最多提高200%。'),
  (330, 'zhCN', '狂暴之怒', '当你受到攻击时，打击你6码内的所有敌人，造成伤害，并使你进入狂怒状态（急速提高25%，持续4秒），每2秒至多触发一次。'),
  (331, 'zhCN', '复仇者之盾', '将你的盾牌掷向20码内最近的敌人，造成伤害。盾牌会弹向10码内的5个敌人，绝不重复命中同一目标。你的护盾每相当于1%最大生命值，伤害提高2%，最多提高200%。'),
  (332, 'zhCN', '壁垒', '猛击你6码内的所有敌人，造成伤害，你的护盾每相当于1%最大生命值，伤害提高2%，最多提高200%。每击中一个敌人就为你的护盾增加1%最大生命值，每次猛击最多增加10%。'),
  (400, 'zhCN', '寒冰箭', '向最近的敌人掷出一枚冰霜箭，造成冰霜伤害并施加1层冰寒。对已冻结的敌人造成的伤害提高50%，且你的冰霜法术必定对其造成致命一击。'),
  (401, 'zhCN', '暴风雪', '冰片轰击最大的敌群，持续4秒，造成冰霜伤害并每秒施加1层冰寒。'),
  (402, 'zhCN', '冰霜新星', '以寒霜轰击你10码内的所有敌人，造成冰霜伤害并施加3层冰寒。'),
  (403, 'zhCN', '火球术', '向最近的敌人掷出一个火球，造成火焰伤害并施加2层燃烧。'),
  (404, 'zhCN', '烈焰风暴', '向最大的敌群降下一道火柱，造成火焰伤害并施加4层燃烧。火焰会灼烧地面4秒，对范围内的敌人造成火焰伤害。'),
  (405, 'zhCN', '炎爆术', '向一个精英或首领掷出巨型火球，若没有则掷向最大的敌群，对目标造成高额火焰伤害，并对其6码内的敌人造成35%的伤害。'),
  (406, 'zhCN', '火焰冲击', '轰击燃烧层数最多的3个敌人，造成火焰伤害，每层燃烧使伤害提高10%，最多计算30层。'),
  (407, 'zhCN', '闪现术', '你的冲刺变为闪现术，使你瞬间传送，充能次数增加1次，冷却时间缩短30%。每次闪现都会在你离开的位置引发一次魔爆术，对10码内的敌人造成奥术伤害。你落地点10码内的敌人获得2层冰寒，且冰霜新星的冷却时间会被重置。占用一个法术槽位。'),
  (408, 'zhCN', '魔爆术', '以奥术能量轰击你10码内的所有敌人，造成奥术伤害。每次闪现落地的位置也会引发爆炸。'),
  (409, 'zhCN', '奥术飞弹', '在1秒内向最近的敌人发射5枚奥术飞弹，每枚造成奥术伤害。每次闪现术后，会一次性向最近的敌人发射全部5枚。'),
  (410, 'zhCN', '召唤元素', '召唤一个元素为你而战，其类型与你大多数法术所属的系别一致。'),
  (411, 'zhCN', '冰霜碎片', '向最近的敌人掷出一枚冰霜箭，造成冰霜伤害并施加1层冰寒，对已冻结的敌人造成的伤害提高50%。随后它会弹向12码内下一个已冻结的敌人，最多弹射6次。你的冰霜法术必定对已冻结的敌人造成致命一击。'),
  (412, 'zhCN', '碎裂', '向最近的敌人掷出一枚冰霜箭，造成冰霜伤害并施加1层冰寒，对已冻结的敌人造成的伤害提高50%。命中已冻结敌人的冰霜箭会将其震碎，对5码内的敌人造成等量伤害。你的冰霜法术必定对已冻结的敌人造成致命一击。'),
  (413, 'zhCN', '深度冻结', '冰片轰击最大的敌群，持续4秒，造成冰霜伤害并每秒施加1层冰寒。在其中被冻结的普通敌人将持续冻结直至效果结束。'),
  (414, 'zhCN', '冰寒刺骨', '冰片轰击最大的敌群，持续4秒，造成冰霜伤害并每秒施加1层冰寒。每当有敌人被冻结在其中，就会损失15%最大生命值（精英为5%，首领为1%）。'),
  (415, 'zhCN', '极寒新星', '寒霜在你上一个寒冰箭目标周围爆发，若目标已消失则改为30码内最近的敌人，造成冰霜伤害并对其10码内的敌人施加3层冰寒。'),
  (416, 'zhCN', '冰霜屏障', '以寒霜轰击你10码内的所有敌人，造成冰霜伤害并施加3层冰寒。每冻结一个敌人就获得一层护盾，可吸收1%最大生命值的伤害，每次施法最多叠加至15%。'),
  (417, 'zhCN', '野火', '向最近的敌人掷出一个火球，造成火焰伤害并施加2层燃烧。在目标存活的6秒内，其燃烧效果每秒会跳向附近一个未燃烧的敌人。'),
  (418, 'zhCN', '活体炸弹', '向最近的敌人掷出一个火球，造成火焰伤害并施加2层燃烧，同时埋下一颗炸弹，在2秒后爆炸，对6码内的敌人造成50%的伤害并施加2层燃烧。'),
  (419, 'zhCN', '烈焰之路', '在最大的敌群中接连降下3根火柱，每根造成火焰伤害并施加4层燃烧。每根火柱会灼烧地面4秒，对范围内的敌人造成火焰伤害。'),
  (420, 'zhCN', '燃烧之地', '在最大的敌群上空召唤一根火柱，造成火焰伤害并施加4层燃烧。火焰会灼烧范围内的敌人4秒，地面继续燃烧6秒，每秒对8码内的敌人施加1层燃烧。'),
  (421, 'zhCN', '陨石术', '一颗陨石坠落砸向最大的敌群，对其8码内的敌人造成高额火焰伤害并施加2层燃烧。陨坑燃烧4秒，每秒对5码内的敌人施加1层燃烧。'),
  (422, 'zhCN', '陨石雨', '7颗陨石坠落砸向最大的敌群，每颗对其3码内造成火焰伤害，敌人每层燃烧使伤害提高10%，最多计算30层。'),
  (423, 'zhCN', '冲击波', '一道火浪轰击你10码内的所有敌人，造成火焰伤害，每层燃烧使伤害提高10%，最多计算30层。被击中的敌人若身上带有燃烧，会喷发火焰，对其5码内最多3个敌人造成40%的伤害。'),
  (424, 'zhCN', '炽热连击', '轰击燃烧层数最多的3个敌人，造成火焰伤害，每层燃烧使伤害提高10%，最多计算30层。此法术每次施放中的首次致命一击会立即施放你的炎爆术；若你没有炎爆术，则改为对目标施放一发炎爆术。'),
  (425, 'zhCN', '相位疾走', '你的冲刺变为闪现术，充能次数增加1次，冷却时间缩短30%。每次闪现都会在你离开的位置引发一次魔爆术，对10码内的敌人造成奥术伤害，命中沿途的所有敌人，并使你免疫伤害1秒。你落地点10码内的敌人获得2层冰寒，且冰霜新星的冷却时间会被重置。'),
  (426, 'zhCN', '微光', '你的冲刺变为闪现术，充能次数增加3次，冷却时间缩短30%。每次闪现都会在你离开的位置引发一次魔爆术，对10码内的敌人造成奥术伤害，并重置魔爆术的冷却时间。你落地点10码内的敌人获得2层冰寒，且冰霜新星的冷却时间会被重置。'),
  (427, 'zhCN', '缓慢时间', '以奥术能量轰击你10码内的所有敌人，造成奥术伤害。每次闪现落地的位置也会引发爆炸。爆炸会留下一个时间泡，持续10秒：泡内的普通敌人移动速度降低60%，泡内所有敌人受到的伤害提高15%。'),
  (428, 'zhCN', '气定神闲', '以奥术能量轰击你10码内的所有敌人，造成奥术伤害。每次闪现落地的位置也会引发爆炸。每次爆炸都会立即施放你的一个其他法术，每0.5秒至多触发一次。'),
  (429, 'zhCN', '奥术弹幕', '在1秒内向最近的敌人发射5枚奥术飞弹，每枚造成奥术伤害。搭配闪现术时，飞弹改为在你移动时积攒，最多40枚，你下一次闪现术会将它们全部射向最近的敌人。'),
  (430, 'zhCN', '奥术强化', '在1秒内向最近的敌人发射5枚奥术飞弹，每枚造成奥术伤害。每次闪现术后，会一次性向最近的敌人发射全部5枚，并使你的法术伤害提高30%，持续4秒。'),
  (431, 'zhCN', '九头蛇', '召唤一条三头九头蛇，向30码内的敌人喷吐冰霜、火焰和奥术箭。每个头会选择不同的敌人。它的冰霜头施加冰寒，火焰头施加燃烧。你走远时它会跟随你。'),
  (432, 'zhCN', '元素轮转', '召唤一个元素，每5秒转换一次系别：水元素施加冰寒，火元素施加燃烧，然后是奥术。'),
  (500, 'zhCN', '惩击', '惩击最近的2个敌人，造成神圣伤害。每次惩击都会使圣言术：惩的冷却时间缩短1秒。'),
  (501, 'zhCN', '恢复', '每秒为你恢复1%最大生命值。生命值全满时，改为惩击30码内最近的敌人，造成神圣伤害。拥有真言术：盾时，超出满生命值的治疗会补充你的护盾，最多补充至护盾上限。'),
  (502, 'zhCN', '圣光圆环', '一道光环击中你12码内的所有敌人，造成神圣伤害，并每命中一个敌人为你恢复0.5%最大生命值，最多2%。'),
  (503, 'zhCN', '圣言术：惩', '圣光打击30码内最强的敌人，造成高额神圣伤害。每次惩击或圣光晕都会使其冷却时间缩短1秒。'),
  (504, 'zhCN', '真言术：盾', '为你施加护盾，可吸收相当于10%最大生命值的伤害；每次施法会将护盾补满而非叠加。持有护盾期间你的移动速度提高10%。'),
  (505, 'zhCN', '苦修', '向过去5秒内攻击过你的敌人发射3枚神圣箭；若没有这样的敌人，则射向最近的敌人，每枚造成神圣伤害并为你恢复0.5%最大生命值。超出满生命值的治疗会转化为护盾，最多为最大生命值的6%。'),
  (506, 'zhCN', '心灵尖啸', '8码内的普通敌人因恐惧而逃跑，持续2秒，每秒受到暗影伤害。精英和首领不受影响。'),
  (507, 'zhCN', '束缚', '打击30码内最强的敌人，造成神圣伤害并将其束缚2秒，束缚期间每秒造成神圣伤害。首领和小首领会被优先打击，但无法被束缚。'),
  (508, 'zhCN', '暗言术：痛', '使35码内离你最远的3个敌人染上6层腐朽。'),
  (509, 'zhCN', '精神鞭笞', '鞭笞20码内最近的敌人，造成暗影伤害，施加1层腐朽并使其减速30%。持续鞭笞该敌人直至其死亡或离开范围。目标身上每层腐朽使伤害提高5%，最多计算30层。'),
  (510, 'zhCN', '心灵震爆', '轰击腐朽层数最多的敌人，造成暗影伤害。其8码内的所有敌人都会获得与其相同的腐朽层数，最多10层。'),
  (511, 'zhCN', '暗影魔', '召唤一只暗影魔，其攻击会施加腐朽，其暗影顺劈会命中前方的所有敌人。它的近战攻击为你恢复0.5%最大生命值。'),
  (512, 'zhCN', '圣火', '以圣火惩击最近的敌人，造成神圣伤害并施加3层燃烧。每次惩击都会使圣言术：惩的冷却时间缩短1秒。'),
  (513, 'zhCN', '灼热之光', '惩击最近的敌人，造成神圣伤害。每第4次惩击还会命中目标6码内的敌人，并使普通敌人昏迷1秒。每次惩击都会使圣言术：惩的冷却时间缩短1秒。'),
  (514, 'zhCN', '圣光回响', '每秒为你恢复1%最大生命值。生命值全满时，改为惩击30码内最近的敌人，造成神圣伤害。任何溢出满生命值的治疗也会触发惩击，每秒至多两次。拥有真言术：盾时，超出满生命值的治疗会补充你的护盾，最多补充至护盾上限。'),
  (515, 'zhCN', '治疗祷言', '每秒为你恢复1%最大生命值。生命值全满时，改为惩击30码内最近的敌人，造成神圣伤害，并跳向附近的2个额外敌人。拥有真言术：盾时，超出满生命值的治疗会补充你的护盾，最多补充至护盾上限。'),
  (516, 'zhCN', '神圣赞美诗', '在2秒内接连爆发3次光环，每次击中你12码内的所有敌人，造成神圣伤害，并每命中一个敌人为你恢复0.5%最大生命值，最多2%。'),
  (517, 'zhCN', '圣光之刃', '一道光环击中你12码内的所有敌人，造成神圣伤害，距离越远伤害越高，最多提高100%，并每命中一个敌人为你恢复0.5%最大生命值，最多2%。'),
  (518, 'zhCN', '圣言术：涤', '圣光打击附近最强的敌人，优先选择精英，造成高额神圣伤害，对其8码内的敌人造成一半伤害，并为你恢复3%的最大生命值。每次惩击或圣光圆环都会使此法术的冷却时间缩短1秒。'),
  (519, 'zhCN', '神化', '圣光打击附近最强的敌人，优先选择精英，造成高额神圣伤害，并重置惩击和圣光圆环的冷却时间。每次惩击或圣光圆环都会使此法术的冷却时间缩短1秒。'),
  (520, 'zhCN', '反射护盾', '为你施加护盾，可吸收相当于10%最大生命值的伤害；每次施法会将护盾补满而非叠加。持有护盾期间你的移动速度提高10%，且护盾吸收的伤害会以神圣伤害的形式返还给攻击者。'),
  (521, 'zhCN', '真言术：壁', '为你施加护盾，可吸收相当于10%最大生命值的伤害，并在你脚下撑起一道防护罩，持续5秒；罩内你受到的伤害降低25%。每次施法会将护盾补满而非叠加。持有护盾期间你的移动速度提高10%。'),
  (522, 'zhCN', '狂喜', '向最近攻击过你的敌人发射3枚神圣箭，持有护盾时改为5枚，每枚造成神圣伤害并为你恢复0.5%最大生命值。溢出满生命值的治疗会转化为护盾。'),
  (523, 'zhCN', '悔悟', '向最近攻击过你的敌人发射3枚神圣箭，每枚造成神圣伤害，命中其4码内的敌人造成一半伤害，并为你恢复0.5%最大生命值。溢出满生命值的治疗会转化为护盾。'),
  (524, 'zhCN', '心灵恐慌', '你8码内的普通敌人因恐惧而逃跑，持续2秒，每秒受到暗影伤害，且受到的所有伤害提高20%。精英、小首领和首领不会逃跑。'),
  (525, 'zhCN', '暗影恐惧', '你8码内的普通敌人因恐惧而逃跑，持续2秒，获得3层腐朽并每秒受到暗影伤害。精英、小首领和首领不会逃跑。'),
  (526, 'zhCN', '光之锁链', '束缚附近最强的敌人，优先选择精英，持续2秒。敌人被束缚时以及束缚期间每秒受到神圣伤害，且受到的所有伤害提高30%。首领和小首领无法被束缚，但仍会受到初次打击。'),
  (527, 'zhCN', '群体束缚', '束缚附近最强的3个敌人，优先选择精英，持续2秒。敌人被束缚时以及束缚期间每秒受到神圣伤害。首领和小首领无法被束缚，但仍会受到初次打击。'),
  (528, 'zhCN', '吸血鬼之触', '使35码内离你最远的3个敌人染上6层腐朽。你的腐朽所造成伤害的2%会为你恢复生命值，每秒最多恢复1%最大生命值。'),
  (529, 'zhCN', '悲惨', '使35码内离你最远的3个敌人染上6层腐朽和1层暗影易伤。'),
  (530, 'zhCN', '心灵灼烧', '鞭笞最近的敌人，对其造成暗影伤害，对其6码内的敌人造成一半伤害，施加1层腐朽并使其减速30%。目标身上每层腐朽使伤害提高5%，最多计算30层。'),
  (531, 'zhCN', '疯狂', '鞭笞最近的敌人，造成暗影伤害，施加1层腐朽并使其减速30%。当它死亡时，其腐朽效果会转移到你的下一个目标身上。目标身上每层腐朽使伤害提高5%，最多计算30层。'),
  (532, 'zhCN', '心灵尖刺', '轰击腐朽层数最多的敌人，造成暗影伤害。其8码内的所有敌人都会获得与其相同的腐朽层数，最多10层，随后其自身的腐朽会立即造成所有剩余伤害。'),
  (533, 'zhCN', '虚空爆发', '轰击腐朽层数最多的敌人，造成暗影伤害。其8码内的所有敌人受到一半伤害，并获得与其相同的腐朽层数，最多10层。'),
  (534, 'zhCN', '心灵魔仆', '召唤一只暗影魔，其攻击会命中目标5码内的敌人，施加腐朽，并为你恢复0.5%最大生命值。'),
  (535, 'zhCN', '虚空之须', '召唤一只暗影魔，其攻击会施加腐朽，并为你恢复0.5%最大生命值。它会每隔6秒定身6码内的普通敌人2秒。'),
  (600, 'zhCN', '影袭', '刺击最近的敌人，造成伤害。'),
  (601, 'zhCN', '剑刃乱舞', '在8秒内，你的单体攻击还会以50%的伤害打击8码内的4个额外敌人。额外攻击会附带你的毒药和起手技。'),
  (602, 'zhCN', '剔骨', '剖开最近的敌人，造成高额伤害，致命一击几率翻倍。击杀敌人后，这一击会传递至8码内的下一个敌人，最多传递3次。'),
  (603, 'zhCN', '杀戮盛筵', '在1.4秒内攻击8次，每次随机命中10码内的一个敌人，造成伤害并附带你的毒药和起手技。每次攻击使剔骨的冷却时间缩短0.5秒。'),
  (604, 'zhCN', '毁伤', '双持匕首刺击最近的敌人，造成伤害，每次刺击施加1层中毒，目标每已有5层中毒便额外施加1层。对已中毒的敌人造成的伤害提高30%。'),
  (605, 'zhCN', '致命毒药', '你的其他技能每次命中都会施加1层中毒。还会向20码内最大的敌群投掷一瓶毒药，造成自然伤害，并对8码内的每个敌人施加4层中毒。'),
  (606, 'zhCN', '刀扇', '向四面八方掷出飞刀，打击10码内的所有敌人，造成伤害并施加2层中毒。每把飞刀都会附带你的毒药和起手技。'),
  (607, 'zhCN', '毒伤', '打击中毒层数最多的3个敌人，造成自然伤害，并附加其中毒效果剩余本应造成的全部伤害，同时保留层数。你的攻击在5秒内额外施加2层中毒。'),
  (608, 'zhCN', '手里剑投掷', '向20码内最近的3个敌人投掷手里剑，优先攻击你尚未命中过的敌人，造成伤害。'),
  (609, 'zhCN', '伏击', '你的其他技能对每个敌人的首次命中之后，会发动一次伏击，造成高额伤害，致命一击几率翻倍。'),
  (610, 'zhCN', '暗影之舞', '在4秒内你的攻击造成的伤害提高30%，且可再次触发伏击，每个敌人每秒一次。'),
  (611, 'zhCN', '闪避', '使你的闪避几率提高50%，持续5秒，最多达到85%。'),
  (612, 'zhCN', '左右开弓', '刺击最近的敌人，造成伤害，随后以副手刺击8码内的另一个敌人。'),
  (613, 'zhCN', '军刀猛击', '刺击最近的敌人，造成伤害。刺击击杀目标时，你会立即刺击下一个最近的敌人，最多连续3次。'),
  (614, 'zhCN', '无尽乱舞', '你的单体攻击始终会以50%的伤害额外打击8码内的2个敌人。额外攻击会附带你的毒药和起手技。'),
  (615, 'zhCN', '暗影之刃', '在8秒内，你的单体攻击还会打击8码内的4个额外敌人，造成50%的暗影伤害。额外攻击可再次触发伏击，每个敌人每秒一次。'),
  (616, 'zhCN', '终结一击', '剖开最近的5个敌人，造成高额伤害，致命一击几率翻倍。击杀敌人后，这一击会传递至8码内的下一个敌人，最多传递3次。'),
  (617, 'zhCN', '致命投掷', '向30码内最强的敌人掷出一把利刃，优先选择精英，造成高额伤害，致命一击几率翻倍。被命中的普通敌人减速50%，持续3秒。击杀敌人后，这一击会传递至8码内的下一个敌人，最多传递3次。'),
  (618, 'zhCN', '杀意', '在2秒内连续攻击8次，每次攻击随机命中10码内的一个敌人，造成伤害。每击杀一个敌人增加2次攻击，最多增加20次。每次攻击使剔骨的冷却时间缩短0.5秒。'),
  (619, 'zhCN', '终幕华章', '在2秒内连续攻击8次，每次攻击随机命中10码内的一个敌人，造成伤害。最后一击还会触发你的剔骨和毒伤（若你拥有它们），且不会触发它们的冷却时间。每次攻击使剔骨的冷却时间缩短0.5秒。'),
  (620, 'zhCN', '剧毒之刃', '双持匕首刺击最近的敌人，造成伤害，每次刺击施加1层中毒（目标每已有5层中毒便额外施加1层）和2层自然易伤。对已中毒的敌人造成的伤害提高30%。'),
  (621, 'zhCN', '出其不意', '双持匕首刺击最近的敌人，造成伤害，目标生命值低于35%时改为刺击3次，每次刺击施加1层中毒（目标每已有5层中毒便额外施加1层）。对已中毒的敌人造成的伤害提高30%。'),
  (622, 'zhCN', '致残毒药', '你的其他技能每次命中都会施加1层中毒，并使普通敌人减速30%。已中毒的敌人受到你造成的伤害提高15%。还会向20码内最大的敌群投掷一瓶毒药，造成自然伤害，并对8码内的每个敌人施加4层中毒。'),
  (623, 'zhCN', '速效毒药', '你的其他技能每次命中都会施加1层中毒，并额外造成30%的自然伤害。还会向20码内最大的敌群投掷一瓶毒药，造成自然伤害，并对8码内的每个敌人施加4层中毒。'),
  (624, 'zhCN', '铁蒺藜', '向四面八方掷出飞刀，打击10码内的所有敌人，造成伤害并施加2层中毒。同时在地面留下铁蒺藜，持续4秒，使敌人减速并每秒施加1层中毒。'),
  (625, 'zhCN', '致命刀扇', '向四面八方掷出飞刀，打击10码内的所有敌人，造成伤害并施加2层中毒。剔骨或毒伤触发时也会掷出飞刀。'),
  (626, 'zhCN', '毒液飞溅', '打击中毒层数最多的3个敌人，造成自然伤害，并额外造成其中毒效果仍将造成的全部伤害，同时保留其层数；还会打击它们8码内所有中毒的敌人，造成自然伤害。你的攻击在5秒内额外施加2层中毒。'),
  (627, 'zhCN', '放血', '打击中毒层数最多的3个敌人，造成自然伤害，并额外造成其中毒效果仍将造成的全部伤害，同时保留其层数。这些敌人及其10码内所有中毒的敌人还会立即承受其中毒效果在接下来4秒内将造成的伤害。你的攻击在5秒内额外施加2层中毒。'),
  (628, 'zhCN', '手里剑风暴', '向20码内最近的2个敌人投掷手里剑，优先攻击你尚未命中过的敌人，造成伤害。每枚手里剑会弹向2个附近的其他敌人。'),
  (629, 'zhCN', '暗影手里剑', '向20码内最近的2个敌人投掷手里剑，优先攻击你尚未命中过的敌人，造成伤害。每枚命中处会留下一道暗影，在1.5秒后爆发，对5码内的敌人造成暗影伤害。'),
  (630, 'zhCN', '偷袭', '你的其他技能对每个敌人的首次命中之后，会发动一次伏击，造成高额伤害，致命一击几率翻倍。伏击会使普通敌人昏迷1秒。'),
  (631, 'zhCN', '发现弱点', '你的其他技能对每个敌人的首次命中之后，会发动一次伏击，造成高额伤害，致命一击几率翻倍。被伏击的敌人在6秒内受到你造成的伤害提高20%。'),
  (632, 'zhCN', '消失', '在4秒内你的攻击造成的伤害提高30%，且可再次触发伏击，每个敌人每秒一次。发动时先消失一次：10码内的普通敌人会丢失你的踪影并眩晕2秒。'),
  (633, 'zhCN', '死亡符记', '4秒内你的攻击造成的伤害提高30%，且可再次触发伏击，每个敌人每秒一次。发动时先以暗影打击14码内最强的5个敌人，造成伤害。'),
  (634, 'zhCN', '还击', '在5秒内你的闪避几率提高50%，且每次闪避都会反击攻击者，造成伤害。'),
  (635, 'zhCN', '烟雾弹', '在5秒内你的闪避几率提高50%，且站在你脚下烟雾中时，敌人的攻击有一半几率未命中你。'),
  (700, 'zhCN', '闪电箭', '向最近的敌人掷出闪电，并弹向1个额外敌人，对每个敌人造成自然伤害并施加1层静电。'),
  (701, 'zhCN', '闪电链', '向最近的敌人掷出闪电，并跳向4个额外敌人，对每个敌人造成自然伤害并施加1层静电。'),
  (702, 'zhCN', '烈焰震击', '震击附近最强的敌人，优先选择精英，造成火焰伤害并施加6层燃烧。'),
  (703, 'zhCN', '大地震击', '震击静电层数最多的敌人，造成自然伤害，每层静电使伤害提高50%。消耗这些层数进行放电，还会命中最多3个附近敌人。每消耗一层静电，恢复1层闪电之盾充能。'),
  (704, 'zhCN', '风怒武器', '挥击最近的敌人，造成伤害。每第3次挥击会唤起风怒：额外挥击2次，同时命中目标4码内的敌人。'),
  (705, 'zhCN', '风暴打击', '以武器和闪电双重打击12码内最近的敌人，造成伤害，施加2层静电和2层自然易伤。算作2次漩涡武器命中。'),
  (706, 'zhCN', '漩涡武器', '你的其他萨满法术和野性狼魂的撕咬每第3次命中会免费向30码内最近的敌人掷出一道闪电箭；若你学会闪电链，则改为向最近的3个敌人，造成自然伤害并施加1层静电。闪电之盾和图腾的命中不计入。'),
  (707, 'zhCN', '野性狼魂', '召唤2头灵魂之狼，它们的撕咬会施加1层静电。每3秒，每头狼会顺劈其前方6码内的所有敌人。'),
  (708, 'zhCN', '灼热图腾', '在你脚下插入一根灼热图腾，向20码内的2个敌人掷出火焰，施加燃烧。你远离时图腾会重新插到你脚下。'),
  (709, 'zhCN', '熔岩图腾', '将一根熔岩图腾掷向25码内最大的敌群。图腾每2秒喷发一次火焰，对8码内的敌人造成火焰伤害并施加1层燃烧，且在范围内没有敌人时会被再次掷出。'),
  (710, 'zhCN', '治疗之泉图腾', '在你脚下插入一根治疗之泉图腾，只要你停留在15码内，它就会每秒为你恢复1%最大生命值。'),
  (711, 'zhCN', '闪电之盾', '以最多3层闪电充能环绕你。每1.5秒，每层你所持有的充能会电击1个10码内的敌人，造成自然伤害并叠加1层静电，每次电击还会为你提供相当于最大生命值0.5%的护盾，最多叠加至5%。攻击你的敌人会消耗一层充能并同样被电击。每1.5秒恢复一层充能。'),
  (712, 'zhCN', '闪电过载', '向最近的敌人掷出闪电，造成自然伤害并施加1层静电。引发静电放电的闪电还会从该敌人身上再掷出一道闪电链。'),
  (713, 'zhCN', '熔岩爆裂', '向燃烧层数最多的敌人掷出熔岩，造成火焰伤害。必定对燃烧中的敌人造成致命一击。'),
  (714, 'zhCN', '元素掌握', '向最近的敌人掷出闪电，闪电最多跳跃10次，对每个敌人造成自然伤害并施加1层静电。每次跳跃造成的伤害降低15%。'),
  (715, 'zhCN', '叉状闪电', '向最近的2个敌人各掷出一道闪电链，每道跳向4个额外敌人，对每个敌人造成自然伤害并施加1层静电。'),
  (716, 'zhCN', '冰霜震击', '震击附近最强的敌人，优先选择精英，造成冰霜伤害并施加6层冰寒。'),
  (717, 'zhCN', '熔岩涌动', '震击附近最强的敌人，优先选择精英，造成火焰伤害并施加6层燃烧。燃烧中的敌人死亡时会立即射出一道闪电箭。'),
  (718, 'zhCN', '地震术', '震击静电层数最多的敌人，造成自然伤害，每层静电使伤害提高50%。消耗这些层数进行放电，还会命中最多3个附近敌人，同时大地震颤4秒，使其中的敌人眩晕并每秒受到自然伤害。每消耗一层静电，恢复1层闪电之盾充能。'),
  (719, 'zhCN', '风暴之眼', '震击静电层数最多的敌人，造成自然伤害，每层静电使伤害提高50%。消耗这些层数进行放电，还会命中最多3个附近敌人。你10码内的每次静电放电还会命中其6码内的敌人。每消耗一层静电，恢复1层闪电之盾充能。'),
  (720, 'zhCN', '火舌武器', '挥击最近的敌人，造成伤害，附加火焰伤害并施加1层燃烧。每第3次挥击会唤起风怒：额外挥击2次，同时命中4码内的敌人并施加3层燃烧。'),
  (721, 'zhCN', '毁灭之风', '挥击最近的敌人，造成伤害。每第3次挥击会唤起风怒：额外挥击2次，同时命中4码内的敌人。每隔15秒，所有挥击都会唤起风怒，持续4秒。'),
  (722, 'zhCN', '熔岩猛击', '以武器和熔岩两次打击12码内最近的敌人，造成伤害，施加2层静电、2层自然易伤和2层燃烧。熔岩对燃烧中的敌人造成的伤害提高50%。算作2次漩涡武器命中。'),
  (723, 'zhCN', '崩雷', '以武器和闪电双重打击12码内最近的敌人，造成伤害，施加2层静电和2层自然易伤。闪电还会命中你8码内的敌人，施加1层静电。算作2次漩涡武器命中。'),
  (724, 'zhCN', '过载', '你的其他萨满法术和野性狼魂的撕咬每第3次命中会免费向最近的3个敌人各掷出一道闪电箭；若你拥有闪电链，则改为向最近的5个敌人掷出，造成自然伤害。图腾的命中不计入。'),
  (725, 'zhCN', '静电涌动', '你的其他萨满法术和野性狼魂的撕咬每第3次命中会免费向最近的敌人掷出一道闪电箭；若你拥有闪电链，则改为向最近的3个敌人掷出，造成自然伤害并施加5层静电，使其立即放电。图腾的命中不计入。'),
  (726, 'zhCN', '元素之魂', '召唤2头火焰、冰霜和闪电形态的灵魂之狼，它们的撕咬会施加燃烧、冰寒或静电。'),
  (727, 'zhCN', '灵魂之群', '召唤2头灵魂之狼，它们的撕咬会施加静电。每次唤起风怒都会召唤一头额外的狼，持续6秒。'),
  (728, 'zhCN', '火焰新星图腾', '在你脚下插入一根灼热图腾，向20码内的一个敌人掷出火焰，施加燃烧。每4秒爆发一次，对8码内的敌人造成火焰伤害并施加3层燃烧，然后重新插到你脚下。'),
  (729, 'zhCN', '天怒图腾', '在你脚下插入一根灼热图腾，向20码内的2个敌人掷出火焰，施加燃烧。图腾15码内的敌人受到的火焰伤害提高15%。'),
  (730, 'zhCN', '液态岩浆', '将一根熔岩图腾掷向25码内最大的敌群。图腾每2秒喷发一次火焰，对8码内的敌人造成火焰伤害并施加1层燃烧，且在范围内没有敌人时会被再次掷出。每次喷发还会向12码内的敌人掷出2团岩浆。'),
  (731, 'zhCN', '大地束缚', '将一根熔岩图腾掷向25码内最大的敌群。图腾每2秒喷发一次火焰，对8码内的敌人造成火焰伤害并施加1层燃烧，同时使其眩晕，且在范围内没有敌人时会被再次掷出。'),
  (732, 'zhCN', '治疗之潮', '召唤一根随你移动的治疗之潮图腾，每秒为你恢复1%最大生命值。'),
  (733, 'zhCN', '治疗之雨', '在你脚下插入一根治疗之泉图腾，只要你停留在15码内，它就会每秒为你恢复1%最大生命值。每3秒还会降雨，对10码内的敌人造成自然伤害。'),
  (734, 'zhCN', '大地之盾', '以最多3层闪电充能环绕你。每1.5秒，每层你所持有的充能会电击1个10码内的敌人，造成自然伤害并叠加1层静电，每次电击还会为你提供相当于最大生命值1.5%的护盾，最多叠加至15%。攻击你的敌人会消耗一层充能并同样被电击。每1.5秒恢复一层充能。'),
  (735, 'zhCN', '静电冲击', '以最多3层闪电充能环绕你。每1.5秒，每层你所持有的充能会电击1个10码内的敌人以及其4码内的敌人，造成自然伤害并叠加1层静电，每次电击还会为你提供相当于最大生命值0.5%的护盾，最多叠加至5%。当敌人攻击你或你的近战攻击命中时，会消耗一层充能再电击一次。每1.5秒恢复一层充能。'),
  (800, 'zhCN', '十字军打击', '打击最近的敌人，造成高额伤害，并对目标5码内的敌人造成30%的伤害。'),
  (801, 'zhCN', '审判', '猛击20码内最强的3个敌人，造成神圣伤害，致命一击几率翻倍。正义圣印使其伤害提高50%；命令圣印还会以一半伤害命中每个目标5码内的敌人；光明圣印每命中一个敌人为你恢复1%最大生命值，最多5%。'),
  (802, 'zhCN', '命令圣印', '你的其他圣骑士法术每第2次打击会释放一次圣光爆发，对目标及其5码内的所有敌人造成神圣伤害。'),
  (803, 'zhCN', '正义圣印', '你的其他圣骑士法术的命中（包括溅射）会额外造成30%的神圣伤害。审判则改为提高50%伤害。奉献、惩罚光环和命令圣印不受影响。'),
  (804, 'zhCN', '奉献', '将你脚下的地面奉献8秒，每秒对站在其上的敌人造成神圣伤害。你站在其上时造成的伤害提高15%。'),
  (805, 'zhCN', '驱邪术', '打击30码内最强的敌人，造成高额神圣伤害。亡灵和恶魔受到三倍伤害，精英和首领受到两倍伤害。你的其他圣骑士法术造成致命一击时，会重置此法术的冷却时间，每秒至多一次。'),
  (806, 'zhCN', '神圣风暴', '圣光在你周围爆发，对10码内的所有敌人造成神圣伤害，并每命中一个敌人为你恢复0.5%最大生命值，最多3%。每次命中的敌人都算作命令圣印的一次打击，最多5次爆发。'),
  (807, 'zhCN', '光明圣印', '你的其他圣骑士法术的每次打击都会为你恢复0.5%最大生命值，每秒至多6次。'),
  (809, 'zhCN', '圣盾术', '一个金色气泡环绕你，抵挡敌人的下一次伤害超过5%最大生命值的攻击。'),
  (810, 'zhCN', '惩戒光环', '以圣光灼烧你10码内的所有敌人，每秒造成神圣伤害。攻击你的敌人受到双倍伤害。'),
  (811, 'zhCN', '制裁之锤', '向20码内最强的敌人掷出一柄战锤，造成神圣伤害并使其昏迷2秒。首领和小首领不会被昏迷。'),
  (812, 'zhCN', '圣光之锤', '圣光之锤砸落在25码内随机的3个敌人身上，每柄对其5码内的所有敌人造成神圣伤害。'),
  (813, 'zhCN', '复仇者之盾', '向25码内最近的敌人掷出一面圣光之盾，造成神圣伤害。它会弹向10码内的另外4个敌人，且不会重复命中同一个敌人。每次命中都算作一次圣骑士打击。'),
  (815, 'zhCN', '十字军热忱', '打击最近的2个敌人，造成高额伤害，并对每个目标5码内的敌人造成50%的伤害。'),
  (816, 'zhCN', '复仇十字军', '打击最近的敌人，造成高额伤害，并对目标5码内的敌人造成30%的伤害。每次打击有15%几率掷出一柄愤怒之锤，造成等量伤害，击杀生命值低于20%的普通敌人。'),
  (817, 'zhCN', '圣光审判', '以圣光之锤猛击20码内最强的3个敌人，造成神圣伤害，致命一击几率翻倍。每命中一个敌人为你恢复1%最大生命值，最多5%，并像审判一样释放你的其他圣印。'),
  (818, 'zhCN', '十字军审判', '以圣光之锤猛击20码内最强的3个敌人，造成神圣伤害，致命一击几率翻倍。被审判的敌人在6秒内受到你造成的伤害提高20%。像审判一样释放你的圣印。'),
  (819, 'zhCN', '十字军圣印', '你的其他圣骑士法术的每次打击都会释放一次圣光爆发，对目标及其5码内的所有敌人造成神圣伤害。'),
  (820, 'zhCN', '公正圣印', '你的其他圣骑士法术每第2次打击会释放一次圣光爆发，对目标及其5码内的所有敌人造成神圣伤害，并使普通敌人和精英昏迷1秒。'),
  (821, 'zhCN', '圣殿骑士圣印', '你的其他圣骑士法术的每次命中，包括溅射和范围命中，都额外造成60%的神圣伤害。'),
  (822, 'zhCN', '复仇圣印', '你的其他圣骑士法术的每次命中，包括溅射和范围命中，都额外造成30%的神圣伤害，对同一敌人的每次命中使该伤害提高20%，最多计算5次。'),
  (823, 'zhCN', '神圣之地', '将你脚下的地面奉献12秒，每秒对站在其上的敌人造成神圣伤害，最多同时存在3块奉献之地。你站在其上时造成的伤害提高25%。'),
  (824, 'zhCN', '祝福之地', '将你脚下的地面奉献8秒，每秒对站在其上的敌人造成神圣伤害。你站在其上时造成的伤害提高15%，并每秒恢复0.5%最大生命值。'),
  (825, 'zhCN', '大驱邪术', '打击30码内最强的3个敌人，造成高额神圣伤害。亡灵和恶魔受到三倍伤害，精英和首领受到两倍伤害。你的其他圣骑士法术造成致命一击时，会重置此法术的冷却时间，每秒至多一次。'),
  (826, 'zhCN', '战争艺术', '打击30码内最强的敌人，造成高额神圣伤害，并对其5码内的敌人造成一半伤害。亡灵和恶魔受到三倍伤害，精英和首领受到两倍伤害。你的其他圣骑士法术造成致命一击时，会重置此法术的冷却时间，每0.5秒至多一次。'),
  (827, 'zhCN', '神圣飓风', '圣光在你周围爆发，对12码内的所有敌人造成神圣伤害，并每命中一个敌人为你恢复0.5%最大生命值，最多5%。每次命中都算作一次命令圣印的打击。'),
  (828, 'zhCN', '灰烬苏醒', '圣光在你周围爆发，对10码内的所有敌人造成神圣伤害，并使普通敌人减速50%；亡灵和恶魔昏迷1秒。每命中一个敌人为你恢复0.5%最大生命值，最多3%。每次命中都算作一次命令圣印的打击。'),
  (829, 'zhCN', '圣疗术', '你的其他圣骑士法术的每次打击都会为你恢复0.5%最大生命值，每秒至多6次。生命值降至30%以下时，将你的生命值恢复全满，每90秒至多触发一次。'),
  (830, 'zhCN', '启迪', '你的其他圣骑士法术的每次打击都会为你恢复0.5%最大生命值，每秒至多6次。致命一击的治疗量提高至三倍。'),
  (831, 'zhCN', '炽热防御者', '一个金色气泡环绕你，抵挡敌人的下一次伤害超过5%最大生命值的攻击。生命值降至30%以下时，使你免疫伤害2秒，每30秒至多触发一次。'),
  (832, 'zhCN', '神圣之盾', '一个金色气泡环绕你，抵挡敌人的下一次伤害超过5%最大生命值的攻击，然后爆裂，对10码内的所有敌人造成神圣伤害。'),
  (833, 'zhCN', '神圣光环', '以圣光灼烧你12码内的所有敌人，每秒造成神圣伤害。攻击你的敌人受到双倍伤害。'),
  (834, 'zhCN', '虔诚光环', '以圣光灼烧你10码内的所有敌人，每秒造成神圣伤害。攻击你的敌人受到双倍伤害。你受到的伤害降低10%。'),
  (835, 'zhCN', '正义之锤', '向20码内最强的敌人掷出一柄战锤，对其及其6码内的所有敌人造成神圣伤害，并使目标昏迷2秒。首领不会被昏迷。'),
  (836, 'zhCN', '忏悔', '向20码内最强的3个敌人掷出战锤，造成神圣伤害并使其昏迷2秒。首领不会被昏迷。'),
  (837, 'zhCN', '天穹震怒', '圣光之锤砸落在25码内随机的5个敌人身上，每柄对其5码内的所有敌人造成神圣伤害。'),
  (838, 'zhCN', '光明之锤', '圣光之锤砸落在25码内随机的3个敌人身上，每柄对其5码内的所有敌人造成神圣伤害。每第3次会有一柄额外的战锤砸向最大的敌群，对其10码内的敌人造成三倍伤害。'),
  (839, 'zhCN', '大十字军', '向25码内最近的敌人掷出一面圣光之盾，造成神圣伤害。它会弹向10码内的另外8个敌人，且不会重复命中同一个敌人。每次命中都算作一次圣骑士打击。'),
  (840, 'zhCN', '正义之盾', '向25码内最近的敌人掷出一面圣光之盾，造成神圣伤害。它会弹向10码内的另外4个敌人，且不会重复命中同一个敌人。每次命中还会对目标5码内的敌人造成一半伤害，并算作一次圣骑士打击。'),
  (900, 'zhCN', '小鬼', '召唤一个小鬼，每次向30码内的敌人掷出2枚火焰箭，使其燃烧。'),
  (901, 'zhCN', '虚空行者', '召唤一个虚空行者，吞噬其附近死亡的敌人。吞噬8个后，它会以虚空新星爆发，击中周围的所有敌人。'),
  (902, 'zhCN', '魅魔', '召唤一个魅魔，她的痛苦之鞭会打击她前方宽广弧线范围内的所有敌人，并施加暗影易伤。'),
  (903, 'zhCN', '恶魔猎犬', '召唤一只恶魔猎犬，其暗影撕咬的伤害随目标身上的每个诅咒效果提高10%，并可打断施法；其暗影顺劈斩会命中前方的所有敌人。每10秒，它会移除你身上的一个有害效果。'),
  (904, 'zhCN', '腐蚀术', '腐蚀30码内的2个敌人，优先选择最近的未带腐朽的敌人，施加1层腐朽；若目标没有腐朽则施加2层。'),
  (905, 'zhCN', '痛苦诅咒', '诅咒30码内的2个敌人，优先选择生命值最高且未被诅咒的敌人，施加1层痛苦；若目标未被诅咒则施加2层。你的暗影箭会为被诅咒的敌人增加1层痛苦。'),
  (906, 'zhCN', '生命吸取', '吸取16码内最近的敌人，每秒造成伤害，并每吸取一个敌人为你恢复1%最大生命值，最多2%。被吸取的敌人受到你的腐朽和痛苦伤害提高20%。'),
  (907, 'zhCN', '暗影箭', '向最近的敌人射出一发暗影箭，造成伤害，目标身上每层腐朽使伤害提高4%，最多30层。夜幕：身上带有你的持续伤害效果而死亡的敌人会触发一发免费暗影箭，每秒至多1发。'),
  (908, 'zhCN', '献祭', '以火焰打击最近的2个敌人，造成伤害并施加2层燃烧。'),
  (909, 'zhCN', '地狱烈焰', '烈焰灼烧你8码内的所有敌人，造成伤害并施加1层燃烧。'),
  (910, 'zhCN', '火焰之雨', '向最大的敌群降下火焰之雨，持续4秒，造成伤害并每秒施加1层燃烧。'),
  (911, 'zhCN', '邪能小鬼', '召唤一个小鬼，每次向30码内的敌人掷出2枚火焰箭，使其燃烧。火焰箭会弹向8码内的2个额外敌人，造成60%的伤害。'),
  (912, 'zhCN', '小鬼成群', '召唤一个小鬼，每次向30码内的敌人掷出2枚火焰箭，使其燃烧。被其火焰箭击杀的敌人会召来一个次级小鬼，持续6秒，最多同时存在6个。'),
  (913, 'zhCN', '牺牲', '召唤一个虚空行者，吞噬其附近死亡的敌人。吞噬8个后，它会以虚空新星爆发，击中周围的所有敌人，并为你施加护盾，可吸收5%最大生命值的伤害。'),
  (914, 'zhCN', '虚空猛击', '召唤一个虚空行者，吞噬其附近死亡的敌人。吞噬8个后，它会以虚空新星爆发，击中周围的所有敌人。它会每隔6秒重击8码内的地面，击退普通敌人。'),
  (915, 'zhCN', '痛苦鞭挞', '召唤一个魅魔，她的痛苦之鞭会打击她周围的所有敌人，并施加暗影易伤。'),
  (916, 'zhCN', '媚惑', '召唤一个魅魔，她的痛苦之鞭会打击她前方宽广弧线范围内的所有敌人，并施加暗影易伤。每8秒她会将20码内最强的普通敌人拉到身边；该敌人受到双倍伤害，持续2秒。'),
  (917, 'zhCN', '法术封锁', '召唤一只恶魔猎犬，其暗影撕咬的伤害随目标身上的每个诅咒效果提高10%，并会打断其8码内的所有施法者；其暗影顺劈斩会命中前方的所有敌人。'),
  (918, 'zhCN', '吞噬词缀', '召唤一只恶魔猎犬，其暗影撕咬的伤害随目标身上的每个诅咒效果提高10%，并会使一个精英的词缀失效6秒，每10秒至多触发一次；其暗影顺劈斩会命中前方的所有敌人。'),
  (919, 'zhCN', '腐蚀之种', '腐蚀最近的2个敌人，施加1层腐朽。被腐蚀的敌人死亡时会爆炸，对其6码内的敌人施加1层腐朽。被爆炸击杀的敌人也会爆炸，最多连锁2次。'),
  (920, 'zhCN', '黑暗收割', '腐蚀最近的2个敌人，施加1层腐朽。每6秒，30码内每个被腐蚀的敌人会立即承受其腐朽在接下来3秒内将造成的伤害，并保留层数。'),
  (921, 'zhCN', '厄运诅咒', '诅咒生命值最高的2个敌人，施加1层痛苦。首次施诅咒10秒后，厄运会降临，造成高额暗影伤害；若其击杀目标，一只末日守卫会为你战斗15秒。你的暗影箭会为受到诅咒的敌人叠加1层痛苦。'),
  (922, 'zhCN', '痛苦回响', '诅咒生命值最高的2个敌人，施加1层痛苦。被诅咒的敌人死亡时，其痛苦会连同所有层数转移到最近的一个未被诅咒的敌人身上。你的暗影箭会为受到诅咒的敌人叠加1层痛苦。'),
  (923, 'zhCN', '吸取灵魂', '吸取16码内最近的敌人，每秒造成伤害并治疗你，每秒至多恢复2%最大生命值。每个在被吸取期间死亡的敌人会给予你一个灵魂：造成的伤害提高5%，持续10秒，最多10个灵魂。被吸取的敌人受到你的腐朽和痛苦伤害提高20%。'),
  (924, 'zhCN', '黑暗契约', '吸取16码内最近的敌人，每秒造成伤害并治疗你，每秒至多恢复2%最大生命值。溢出满生命值的治疗会使你的恶魔造成的伤害提高30%，持续4秒。被吸取的敌人受到你的腐朽和痛苦伤害提高20%。'),
  (925, 'zhCN', '混沌箭', '向最近的敌人射出一发混沌箭，造成伤害，目标身上每层腐朽使伤害提高4%，最多30层。每第4发会对目标及其8码内的所有敌人造成致命一击，伤害为150%。夜幕：身上带有你的持续伤害效果而死亡的敌人会射出一发免费的箭，每秒最多1发。'),
  (926, 'zhCN', '暗影箭幕', '向最近的敌人射出一发暗影箭，造成伤害，目标身上每层腐朽使伤害提高4%，最多30层。夜幕：身上带有你的持续伤害效果而死亡的敌人会射出一发免费的箭，每秒最多1发，该箭会跳向附近的2个敌人，造成一半伤害。'),
  (927, 'zhCN', '燃烧', '以邪能火焰打击最近的2个敌人，造成伤害并施加2层燃烧。火焰会蔓延至每个目标5码内的所有敌人，造成一半伤害并施加1层燃烧。'),
  (928, 'zhCN', '暗影烈焰', '以邪能火焰打击最近的2个敌人，造成伤害并施加2层燃烧和1层腐朽。'),
  (929, 'zhCN', '地狱火', '邪能烈焰灼烧你8码内的所有敌人，造成伤害并施加1层燃烧。火圈会随你的生命值降低而扩大，最多扩大60%。'),
  (930, 'zhCN', '恶魔献祭', '邪能烈焰灼烧你8码内的所有敌人，造成伤害并施加1层燃烧。你的恶魔也会燃烧，对其6码内的敌人造成一半伤害。'),
  (931, 'zhCN', '召唤地狱火', '向最大的敌群降下邪能烈焰之雨，持续4秒，施加燃烧。每次降雨结束时都会有一只地狱火砸落，造成伤害并使6码内的普通敌人昏迷1秒；随后它会为你战斗8秒。'),
  (932, 'zhCN', '混乱之雨', '向最大的3个敌群降下邪能烈焰之雨，持续4秒，造成伤害并每秒施加1层燃烧。'),
  (1001, 'zhCN', '星火术', '召下星光打击最强的敌人，造成高额奥术伤害。枭兽形态下获得强化。'),
  (1002, 'zhCN', '月火术', '灼烧30码内的2个敌人，优先选择未中月火术的敌人，造成奥术伤害并施加1层月火术。枭兽形态下获得强化。'),
  (1003, 'zhCN', '飓风', '风暴在最大的敌群上空肆虐4秒，每秒造成自然伤害并使其眩晕。枭兽形态下获得强化。'),
  (1004, 'zhCN', '斜掠', '斜掠最近的3个敌人，造成伤害并施加2层流血。猎豹形态下获得强化。'),
  (1005, 'zhCN', '撕碎', '撕碎流血层数最多的敌人，造成伤害，目标每层流血使伤害提高3%。猎豹形态下获得强化。'),
  (1006, 'zhCN', '横扫', '横扫附近的所有敌人，造成伤害。巨熊形态下获得强化。'),
  (1007, 'zhCN', '狂暴恢复', '每秒根据附近的敌人数量为你恢复生命值，每个敌人恢复0.25%最大生命值，最多计算5个。巨熊形态下获得强化。'),
  (1008, 'zhCN', '回春术', '每秒为你恢复0.3%最大生命值，并抽打10码内最近的3个敌人，造成自然伤害。超出满生命值的治疗会使你的攻击和持续伤害效果的结算频率在3秒内提高15%。生命之树形态下获得强化。'),
  (1009, 'zhCN', '自然之力', '召唤2个树人，它们的攻击会施加1层月火术。每6秒，每个树人定身其目标及5码内的普通敌人2秒。生命之树形态下获得强化，并额外召唤1个树人。'),
  (1010, 'zhCN', '纠缠根须', '缠绕25码内最近的3个敌人，造成自然伤害，并定身普通敌人2秒。生命之树形态下获得强化。'),
  (1011, 'zhCN', '宁静', '使空气平静4秒。每秒对附近的敌人造成自然伤害，并为你恢复0.5%最大生命值。生命之树形态下获得强化。'),
  (1012, 'zhCN', '荆棘', '攻击你的敌人受到自然伤害，并被施加2层月火术。巨熊形态下获得强化。'),
  (1013, 'zhCN', '变形', '按R键变形为下一个形态。德鲁伊法术在对应形态下造成的伤害和治疗提高30%。|n|n|cffffffff枭兽形态：|r愤怒会打击最近的敌人，造成自然伤害并溅射5码内的敌人。每3秒，星落术会打击3个中了月火术的敌人。|n|n|cffffffff猎豹形态：|r爪击最近的敌人，造成物理伤害并施加1层流血，同时溅射5码内的敌人。攻击速度提高50%。移动速度提高15%。致命一击会施加1层流血。|n|n|cffffffff巨熊形态：|r重殴最近的敌人，造成物理伤害，并溅射5码内的敌人。受到的伤害降低35%，但其他形态的法术造成的伤害和治疗降低20%。每有一个8码内的敌人，横扫的伤害提高8%，最多计算8个敌人。每6秒发出咆哮，使10码内的敌人眩晕，并使其伤害降低25%，持续4秒。|n|n|cffffffff生命之树：|r藤蔓抽打最近的3个敌人，造成自然伤害，并溅射5码内的敌人，每次命中为你恢复0.3%最大生命值。额外召唤1个树人。回春术的绽放速度加快50%。'),
  (1014, 'zhCN', '星光迸发', '召下星光打击最强的敌人，造成高额奥术伤害。枭兽形态下获得强化。星光会迸发，对附近的敌人造成15%的伤害并施加月火术。'),
  (1015, 'zhCN', '流星', '召下星光打击最强的敌人，造成高额奥术伤害。枭兽形态下获得强化。中了月火术的敌人有几率被流星击中。'),
  (1016, 'zhCN', '阳炎术', '灼烧最近的2个敌人，造成奥术伤害并施加1层月火术。枭兽形态下获得强化。月火术会蔓延至每个目标附近最多3个敌人。'),
  (1017, 'zhCN', '满月', '灼烧最近的2个敌人，造成奥术伤害并施加1层月火术。枭兽形态下获得强化。敌人身上每叠至第10层月火术，就会召下一轮满月，对其及附近的敌人造成奥术伤害。'),
  (1018, 'zhCN', '台风', '风暴在最大的敌群上空肆虐4秒，每秒造成自然伤害并使其眩晕。枭兽形态下获得强化。风暴结束时爆发，造成双倍伤害并击退敌人。'),
  (1019, 'zhCN', '月暴', '风暴在最大的敌群上空肆虐4秒，每秒造成自然伤害并使其眩晕。枭兽形态下获得强化。每2秒，风暴会使其中的敌人染上月火术。'),
  (1020, 'zhCN', '痛击', '痛击附近的所有敌人，造成伤害并施加1层流血。猎豹形态下获得强化。'),
  (1021, 'zhCN', '猛虎之怒', '斜掠最近的3个敌人，造成伤害并施加2层流血。猎豹形态下获得强化。每次斜掠每命中一个敌人，使你获得5%急速，持续4秒，最多25%。'),
  (1022, 'zhCN', '裂伤', '撕碎流血层数最多的敌人，造成伤害，目标每层流血使伤害提高3%。猎豹形态下获得强化。还会撕裂最多4个附近敌人，造成25%的伤害。'),
  (1023, 'zhCN', '凶猛撕咬', '撕碎流血层数最多的敌人，造成伤害，目标每层流血使伤害提高3%。猎豹形态下获得强化。若其击杀目标，则会撕咬下一个流血层数最多的敌人，最多连续3次。'),
  (1024, 'zhCN', '割裂', '横扫附近的所有敌人，造成伤害。巨熊形态下获得强化。施加1层流血。'),
  (1025, 'zhCN', '乌索尔漩涡', '横扫附近的所有敌人，造成伤害。巨熊形态下获得强化。留下一个漩涡，持续3秒，每秒造成50%的伤害并使其中的敌人眩晕。'),
  (1026, 'zhCN', '血腥狂乱', '每秒根据附近的敌人数量为你恢复生命值，每个敌人恢复0.25%最大生命值，最多计算5个。巨熊形态下获得强化。每次治疗还会重殴最多5个附近的敌人，造成伤害。'),
  (1027, 'zhCN', '树皮术', '每秒根据附近的敌人数量为你恢复生命值，每个敌人恢复0.25%最大生命值，最多计算5个。巨熊形态下获得强化。每次治疗还会使你获得等量的护盾，最多可吸收相当于10%最大生命值的伤害。'),
  (1028, 'zhCN', '生命绽放', '为你恢复0.3%最大生命值。其多刺的花朵会抽打最近的3个敌人，造成自然伤害。生命之树形态下获得强化。每第4次绽放会为你恢复1%最大生命值，并对附近所有敌人造成自然伤害。溢出满生命值的治疗会使你的法术攻击频率提高15%，持续3秒。'),
  (1029, 'zhCN', '繁花绽放', '在你脚下生长一圈花环，持续4秒。身处其中时，你每秒恢复0.3%最大生命值，其中的敌人受到自然伤害。生命之树形态下获得强化。'),
  (1030, 'zhCN', '战争古树', '召唤一棵战争古树。每3秒它会跺地一次，对附近敌人造成自然伤害并施加月火术。生命之树形态下获得强化。'),
  (1031, 'zhCN', '真菌生长', '召唤2个树人。它们的攻击会施加月火术，并每6秒定身其目标及附近敌人2秒。生命之树形态下获得强化，并额外召唤1个树人。它们的根须会种下蘑菇，在3秒后爆发，对附近敌人造成自然伤害。'),
  (1032, 'zhCN', '群体缠绕', '根须缠绕最近的3个敌人，造成自然伤害并使其定身2秒。生命之树形态下获得强化。根须会蔓延至附近的其他敌人。'),
  (1033, 'zhCN', '勒紧藤蔓', '根须缠绕最近的3个敌人，造成自然伤害并使其定身2秒。生命之树形态下获得强化。被定身的敌人每秒受到自然伤害，每有一个敌人为你恢复0.05%最大生命值，每秒最多0.5%。'),
  (1034, 'zhCN', '涟漪扩散', '使空气平静4秒。每秒对附近的敌人造成自然伤害，并为你恢复0.5%最大生命值。生命之树形态下获得强化。每跳的波及范围扩大3码。'),
  (1035, 'zhCN', '蔓生', '使空气平静4秒。每秒对附近的敌人造成自然伤害，并为你恢复0.5%最大生命值。生命之树形态下获得强化。溢出的治疗会转化为额外伤害，对附近敌人最多造成60%的额外伤害。'),
  (1036, 'zhCN', '荆棘丛生', '攻击你的敌人受到自然伤害，并被施加2层月火术。巨熊形态下获得强化。荆棘还会打击附近的所有其他敌人，造成50%的伤害。'),
  (1037, 'zhCN', '自然之握', '攻击你的敌人受到自然伤害，并被施加2层月火术。巨熊形态下获得强化。攻击你的敌人会被定身1秒。'),
  (1038, 'zhCN', '变形奔涌', '按R键变形为下一个形态。德鲁伊法术在对应形态下造成的伤害和治疗提高30%。|n|n|cffffffff枭兽形态：|r愤怒打击最近的敌人，造成自然伤害并溅射附近敌人。每3秒，星落术会打击3个中了月火术的敌人。|n|n|cffffffff猎豹形态：|r爪击最近的敌人，造成物理伤害并施加流血。移动速度提高15%。致命一击会造成流血。|n|n|cffffffff巨熊形态：|r重殴最近的敌人，造成物理伤害。受到的伤害降低35%，但其他形态的法术造成的伤害降低20%。每有一个附近敌人，横扫的伤害提高8%。每6秒发出咆哮，使附近敌人眩晕并使其伤害降低25%。|n|n|cffffffff生命之树：|r藤蔓抽打3个敌人，造成自然伤害，每次命中为你恢复0.3%最大生命值。额外召唤1个树人。回春术的绽放速度加快50%。|n|n|cffffffff变形奔涌：|r进入一个形态时释放其威力，每个形态每6秒一次。枭兽召下星落打击5个敌人，猎豹使附近敌人叠加2层流血，巨熊发出咆哮，生命之树定身附近敌人并为你恢复2%最大生命值。'),
  (1039, 'zhCN', '灵魂形态', '按R键变形为下一个形态。德鲁伊法术在对应形态下造成的伤害和治疗提高30%。|n|n|cffffffff枭兽形态：|r愤怒打击最近的敌人，造成自然伤害并溅射附近敌人。每3秒，星落术会打击3个中了月火术的敌人。|n|n|cffffffff猎豹形态：|r爪击最近的敌人，造成物理伤害并施加流血。移动速度提高15%。致命一击会造成流血。|n|n|cffffffff巨熊形态：|r重殴最近的敌人，造成物理伤害。受到的伤害降低35%，但其他形态的法术造成的伤害降低20%。每有一个附近敌人，横扫的伤害提高8%。每6秒发出咆哮，使附近敌人眩晕并使其伤害降低25%。|n|n|cffffffff生命之树：|r藤蔓抽打3个敌人，造成自然伤害，每次命中为你恢复0.3%最大生命值。额外召唤1个树人。回春术的绽放速度加快50%。|n|n|cffffffff灵魂形态：|r你离开的形态会以灵魂形态存留6秒，以25%的伤害继续攻击。');
